'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import type {PaymentScope} from '@/lib/billing-payment-entry';
import {postingRequest,postingResult,type BillingPostingRequest} from '@/lib/billing-posting-request';
import {BillingPostingReview} from './billing-posting-review';
import {billingDollars} from './billing-accounts';
type Props=PaymentScope&{posted?:boolean;payment:{payment_id:string;kind:string;amount_minor:string};onSaved:(journal:string)=>void;onBusyChange?:(busy:boolean)=>void};
export function PostBillingPayment(props:Props){return <Posting key={[props.actor,props.tenant,props.property,props.account,props.payment.payment_id].join('/')} {...props}/>}
function Posting(props:Props){
 const key=['irp-billing-post',props.actor,props.tenant,props.property,props.account,props.payment.payment_id].join('/');
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(key),pending=raw?postingRequest(JSON.parse(raw),props):null;if(pending&&pending.payment!==props.payment.payment_id)throw Error();return {pending,error:''}}catch{return {pending:null,error:'Saved ledger request could not be read. Restore browser storage before continuing.'}}});
 const [pending,setPending]=useState<BillingPostingRequest|null>(initial.pending),[draft,setDraft]=useState<BillingPostingRequest|null>(null),[busy,setBusy]=useState(false),[reviewBusy,setReviewBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState('');
 const [cancelReason,setCancelReason]=useState(''),[cancelled,setCancelled]=useState(false);
 const lock=useRef(false),alive=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);useEffect(()=>{props.onBusyChange?.(busy||reviewBusy);return()=>props.onBusyChange?.(false)},[busy,reviewBusy,props.onBusyChange]);
 async function save(check=false){const r=pending??draft;if(!r||lock.current||initial.error||(!check&&r.cancellation))return;lock.current=true;setBusy(true);setError('');try{postingRequest(r,props);sessionStorage.setItem(key,JSON.stringify(r));setPending(r);
  const value=await hotelRpc(check?'billing_posting_status':'post_billing_payment',{p_tenant:r.tenant,p_property:r.property,p_account:r.account,p_request:r.request,...(!check?{p_payment:r.payment,p_clearing:r.clearing,p_allocations:r.allocations,p_review:r.review,p_period:r.period,p_date:r.date,p_description:r.description,p_confirmed:true}:{})});const journal=postingResult(value,r,check);
  if(!alive.current)return;if(!journal){setNotice('No saved posting found. Retry this same request.');return}sessionStorage.removeItem(key);setPending(null);setDraft(null);setNotice('Payment posted to the ledger. No money moved.');props.onSaved(journal);
 }catch{if(alive.current)setError('Posting could not be confirmed. Check its result or retry the saved request.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function cancel(){if(!pending||lock.current||initial.error)return;lock.current=true;setBusy(true);setError('');try{const r=postingRequest({...pending,cancellation:pending.cancellation??cancelReason.trim()},props);sessionStorage.setItem(key,JSON.stringify(r));setPending(r);
  const v=await hotelRpc<Record<string,unknown>>('retire_billing_posting',{p_tenant:r.tenant,p_property:r.property,p_account:r.account,p_request:r.request,p_reason:r.cancellation,p_confirmed:true});
  if(v.tenant_id!==r.tenant||v.property_id!==r.property||v.account_id!==r.account||v.request_id!==r.request||v.actor_id!==r.actor||v.reason!==r.cancellation||v.retired!==true||v.money_moved!==false)throw Error('Cancellation response does not match.');
  if(!alive.current)return;sessionStorage.removeItem(key);setPending(null);setDraft(null);setCancelled(true);setNotice('Unsaved posting cancelled. No journal was posted.');
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation could not be confirmed. Retry it.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 const current=pending??draft;
 return <section aria-label="Post company payment">{error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}<fieldset disabled={busy||!!initial.error} style={{border:0,padding:0,margin:0}}>{!current&&!notice&&!props.posted&&<BillingPostingReview {...props} onBusyChange={setReviewBusy} onReview={value=>{try{setDraft(postingRequest({...value,version:1,request:crypto.randomUUID()},props));setError('')}catch(e){setError(e instanceof Error?e.message:'Invalid posting review.')}}}/>}{cancelled&&!current&&<button className="secondary" onClick={()=>{setCancelled(false);setNotice('');setCancelReason('')}}>Prepare replacement posting</button>}{!current&&props.posted&&<p>This payment is already posted.</p>}{current&&<><h3>Confirm ledger posting</h3><p>{current.description} · {current.date} · {billingDollars(String(current.review.amount_minor))}</p><div style={{overflowX:'auto'}}><table><caption>Reviewed ledger entries</caption><thead><tr><th scope="col">Account</th><th scope="col">Debit</th><th scope="col">Credit</th></tr></thead><tbody>{(current.review.lines as {account_id:string;side:string;amount_minor:string}[]).map(line=><tr key={line.account_id}><th scope="row">{current.accountLabels?.[line.account_id]??line.account_id}</th><td>{line.side==='debit'?billingDollars(line.amount_minor):'—'}</td><td>{line.side==='credit'?billingDollars(line.amount_minor):'—'}</td></tr>)}</tbody></table></div><p>No payment will be collected.</p><button className="primary" disabled={!!current.cancellation} onClick={()=>void save()}>{pending?'Retry saved posting':'Confirm ledger posting'}</button>{pending?<><button className="secondary" onClick={()=>void save(true)}>Check posting result</button><label className="field">Cancel unsaved posting reason<textarea maxLength={500} disabled={!!pending.cancellation} value={pending.cancellation??cancelReason} onChange={e=>setCancelReason(e.target.value)}/></label><button className="secondary" onClick={()=>void cancel()}>{pending.cancellation?'Retry posting cancellation':'Cancel unsaved posting'}</button></>:<button className="secondary" onClick={()=>setDraft(null)}>Edit posting details</button>}</>}</fieldset></section>;
}
